<?php $v=static fn($k,$d='')=>old($k,$item->{$k}??$d);$selected=explode(',',(string)$v('candidate_statuses','eligible')); ?><div class="right_col" role="main"><h2><?= $item?'Edit':'Create' ?> Admission Test</h2><div class="card shadow-sm"><div class="card-body"><?= form_open('school/admission/tests/save') ?><input type="hidden" name="token" value="<?= esc($item->token??'') ?>"><div class="row"><div class="col-md-6 mb-3"><label>Circular *</label><select class="form-control" name="circular_id"><?php foreach($circularItems as $c): ?><option value="<?= $c->id ?>" <?= $v('circular_id')==$c->id?'selected':'' ?>><?= esc($c->title) ?></option><?php endforeach ?></select></div><div class="col-md-6 mb-3"><label>Test title *</label><input class="form-control" name="title" value="<?= esc($v('title')) ?>" required></div><div class="col-md-3 mb-3"><label>Date *</label><input type="date" class="form-control" name="test_date" value="<?= esc($v('test_date')) ?>" required></div><div class="col-md-3 mb-3"><label>Reporting time</label><input type="time" class="form-control" name="reporting_time" value="<?= esc($v('reporting_time')) ?>"></div><div class="col-md-3 mb-3"><label>Start time *</label><input type="time" class="form-control" name="start_time" value="<?= esc($v('start_time')) ?>" required></div><div class="col-md-3 mb-3"><label>End time</label><input type="time" class="form-control" name="end_time" value="<?= esc($v('end_time')) ?>"></div><div class="col-md-3 mb-3"><label>Total marks *</label><input type="number" step="0.01" class="form-control" name="total_marks" value="<?= esc($v('total_marks',100)) ?>"></div><div class="col-md-3 mb-3"><label>Pass marks *</label><input type="number" step="0.01" class="form-control" name="pass_marks" value="<?= esc($v('pass_marks',40)) ?>"></div><div class="col-md-3 mb-3"><label>Status</label><select class="form-control" name="status"><?php foreach(['draft','published','completed','cancelled'] as $s): ?><option value="<?= $s ?>" <?= $v('status','draft')===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></div><div class="col-12 mb-3"><label>Candidate statuses</label><div><?php foreach(['submitted','under_review','eligible','selected','admission_pending'] as $s): ?><label class="me-3"><input type="checkbox" name="candidate_statuses[]" value="<?= $s ?>" <?= in_array($s,$selected,true)?'checked':'' ?>> <?= ucwords(str_replace('_',' ',$s)) ?></label><?php endforeach ?></div></div><div class="col-12 mb-3"><label>Instructions</label><textarea class="form-control" name="instructions" rows="4"><?= esc($v('instructions')) ?></textarea></div></div><button class="btn btn-primary">Save test</button></form></div></div></div>
